def simplify_path(path):
    parts = path.split('/')
    result = []
    for part in parts:
        if part == '' or part == '.':
            continue                                                       # empty segments (from // or trailing /) and '.' add nothing
        elif part == '..':
            if result:
                result.pop()                                               # go up one directory, if not already at the root
        else:
            result.append(part)                                            # a genuine directory/file name: keep it
    return '/' + '/'.join(result)


if __name__ == "__main__":
    print(simplify_path("/home/user/Documents/../Pictures"))

