import java.util.*;

public class Main {
    String simplifyPath(String path) {
        String[] parts = path.split("/");
        Deque<String> result = new ArrayDeque<>();
        for (String part : parts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;                                                            // empty segments (from // or trailing /) and '.' add nothing
            } else if (part.equals("..")) {
                if (!result.isEmpty()) result.pollLast();                              // go up one directory, if not already at the root
            } else {
                result.addLast(part);                                                 // a genuine directory/file name: keep it
            }
        }
        return "/" + String.join("/", result);
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.simplifyPath("/home/user/Documents/../Pictures"));
    }
}

